#ifndef PBNFC_WORKER_POOL_H
#define PBNFC_WORKER_POOL_H

#include <pthread.h>
#include <stdbool.h>
#include <stddef.h>

#define PBNFC_WORKER_POOL_SIZE 8U

struct PbnfcWorkerPool;

typedef struct {
    struct PbnfcWorkerPool *pool;
    size_t worker_index;
} PbnfcWorkerPoolStart;

/*
 * A job is invoked exactly once by each persistent worker for every
 * pbnfc_worker_pool_run call.  worker_index is stable for the lifetime of
 * the pool and is in the range [0, PBNFC_WORKER_POOL_SIZE).
 */
typedef bool (*PbnfcWorkerPoolJob)(size_t worker_index, void *context);

typedef struct PbnfcWorkerPool {
    pthread_t threads[PBNFC_WORKER_POOL_SIZE];
    PbnfcWorkerPoolStart starts[PBNFC_WORKER_POOL_SIZE];
    pthread_mutex_t mutex;
    pthread_cond_t work_available;
    pthread_cond_t work_complete;
    PbnfcWorkerPoolJob job;
    void *job_context;
    size_t thread_count;
    size_t completed_count;
    unsigned long generation;
    bool job_failed;
    bool running;
    bool shutdown_requested;
    bool synchronization_initialized;
} PbnfcWorkerPool;

/* Create exactly PBNFC_WORKER_POOL_SIZE persistent workers. */
bool pbnfc_worker_pool_init(PbnfcWorkerPool *pool);

/*
 * Run one generation and wait until every worker has completed its callback.
 * Only one generation may be active at a time.  A false callback result is
 * reported as false after all workers have still been allowed to finish.
 */
bool pbnfc_worker_pool_run(PbnfcWorkerPool *pool,
                           PbnfcWorkerPoolJob job,
                           void *context);

/* Stop and join all workers. Safe to call more than once. */
void pbnfc_worker_pool_shutdown(PbnfcWorkerPool *pool);

/* Release synchronization resources after shutdown. */
void pbnfc_worker_pool_free(PbnfcWorkerPool *pool);

size_t pbnfc_worker_pool_worker_count(const PbnfcWorkerPool *pool);

#endif
--- src/worker_pool.c ---
#include "worker_pool.h"

#include <string.h>

static void *worker_main(void *argument)
{
    PbnfcWorkerPoolStart *start = (PbnfcWorkerPoolStart *)argument;
    PbnfcWorkerPool *pool = start->pool;
    const size_t worker_index = start->worker_index;
    unsigned long observed_generation = 0UL;

    for (;;) {
        PbnfcWorkerPoolJob job;
        void *context;
        bool succeeded;

        (void)pthread_mutex_lock(&pool->mutex);
        while (!pool->shutdown_requested &&
               observed_generation == pool->generation) {
            (void)pthread_cond_wait(&pool->work_available, &pool->mutex);
        }
        if (pool->shutdown_requested) {
            (void)pthread_mutex_unlock(&pool->mutex);
            return NULL;
        }
        observed_generation = pool->generation;
        job = pool->job;
        context = pool->job_context;
        (void)pthread_mutex_unlock(&pool->mutex);

        succeeded = job(worker_index, context);

        (void)pthread_mutex_lock(&pool->mutex);
        if (!succeeded) {
            pool->job_failed = true;
        }
        ++pool->completed_count;
        if (pool->completed_count == pool->thread_count) {
            (void)pthread_cond_signal(&pool->work_complete);
        }
        (void)pthread_mutex_unlock(&pool->mutex);
    }
}

bool pbnfc_worker_pool_init(PbnfcWorkerPool *pool)
{
    size_t index;
    int result;

    if (pool == NULL) {
        return false;
    }
    (void)memset(pool, 0, sizeof(*pool));
    result = pthread_mutex_init(&pool->mutex, NULL);
    if (result != 0) {
        return false;
    }
    result = pthread_cond_init(&pool->work_available, NULL);
    if (result != 0) {
        (void)pthread_mutex_destroy(&pool->mutex);
        return false;
    }
    result = pthread_cond_init(&pool->work_complete, NULL);
    if (result != 0) {
        (void)pthread_cond_destroy(&pool->work_available);
        (void)pthread_mutex_destroy(&pool->mutex);
        return false;
    }
    pool->synchronization_initialized = true;

    for (index = 0U; index < PBNFC_WORKER_POOL_SIZE; ++index) {
        pool->starts[index].pool = pool;
        pool->starts[index].worker_index = index;
        result = pthread_create(&pool->threads[index],
                                NULL,
                                worker_main,
                                &pool->starts[index]);
        if (result != 0) {
            pbnfc_worker_pool_shutdown(pool);
            pbnfc_worker_pool_free(pool);
            return false;
        }
        pool->thread_count = index + 1U;
    }
    return true;
}

bool pbnfc_worker_pool_run(PbnfcWorkerPool *pool,
                           PbnfcWorkerPoolJob job,
                           void *context)
{
    bool succeeded;

    if (pool == NULL || job == NULL || !pool->synchronization_initialized) {
        return false;
    }
    (void)pthread_mutex_lock(&pool->mutex);
    if (pool->shutdown_requested ||
        pool->thread_count != PBNFC_WORKER_POOL_SIZE || pool->running) {
        (void)pthread_mutex_unlock(&pool->mutex);
        return false;
    }
    pool->job = job;
    pool->job_context = context;
    pool->completed_count = 0U;
    pool->job_failed = false;
    pool->running = true;
    ++pool->generation;
    (void)pthread_cond_broadcast(&pool->work_available);
    while (pool->completed_count != pool->thread_count) {
        (void)pthread_cond_wait(&pool->work_complete, &pool->mutex);
    }
    succeeded = !pool->job_failed;
    pool->running = false;
    (void)pthread_mutex_unlock(&pool->mutex);
    return succeeded;
}

void pbnfc_worker_pool_shutdown(PbnfcWorkerPool *pool)
{
    size_t index;
    size_t thread_count;

    if (pool == NULL || !pool->synchronization_initialized) {
        return;
    }
    (void)pthread_mutex_lock(&pool->mutex);
    if (pool->shutdown_requested) {
        thread_count = pool->thread_count;
        (void)pthread_mutex_unlock(&pool->mutex);
    } else {
        pool->shutdown_requested = true;
        (void)pthread_cond_broadcast(&pool->work_available);
        thread_count = pool->thread_count;
        (void)pthread_mutex_unlock(&pool->mutex);
    }
    for (index = 0U; index < thread_count; ++index) {
        (void)pthread_join(pool->threads[index], NULL);
    }
    pool->thread_count = 0U;
}

void pbnfc_worker_pool_free(PbnfcWorkerPool *pool)
{
    if (pool == NULL || !pool->synchronization_initialized) {
        return;
    }
    pbnfc_worker_pool_shutdown(pool);
    (void)pthread_cond_destroy(&pool->work_complete);
    (void)pthread_cond_destroy(&pool->work_available);
    (void)pthread_mutex_destroy(&pool->mutex);
    (void)memset(pool, 0, sizeof(*pool));
}

size_t pbnfc_worker_pool_worker_count(const PbnfcWorkerPool *pool)
{
    if (pool == NULL || !pool->synchronization_initialized ||
        pool->shutdown_requested) {
        return 0U;
    }
    return pool->thread_count;
}
--- tests/worker_pool_core_smoke.c ---
#include "worker_pool.h"

#include <stdio.h>
#include <string.h>

typedef struct {
    pthread_mutex_t mutex;
    size_t calls[PBNFC_WORKER_POOL_SIZE];
    pthread_t thread_ids[PBNFC_WORKER_POOL_SIZE];
    bool have_thread_ids;
    bool fail_worker;
} Probe;

static int fail(const char *detail)
{
    (void)fprintf(stderr, "worker pool smoke: %s\n", detail);
    return 1;
}

static bool record_job(size_t worker_index, void *context)
{
    Probe *probe = (Probe *)context;
    pthread_t current = pthread_self();

    (void)pthread_mutex_lock(&probe->mutex);
    ++probe->calls[worker_index];
    if (!probe->have_thread_ids) {
        probe->thread_ids[worker_index] = current;
    } else if (!pthread_equal(probe->thread_ids[worker_index], current)) {
        probe->have_thread_ids = false;
    }
    (void)pthread_mutex_unlock(&probe->mutex);
    return !probe->fail_worker || worker_index != 3U;
}

int main(void)
{
    PbnfcWorkerPool pool = {0};
    Probe probe = {0};
    size_t index;

    if (pthread_mutex_init(&probe.mutex, NULL) != 0) {
        return fail("probe mutex initialization failed");
    }
    if (!pbnfc_worker_pool_init(&pool) ||
        pbnfc_worker_pool_worker_count(&pool) !=
            PBNFC_WORKER_POOL_SIZE) {
        pbnfc_worker_pool_free(&pool);
        (void)pthread_mutex_destroy(&probe.mutex);
        return fail("pool did not create exactly eight workers");
    }
    if (!pbnfc_worker_pool_run(&pool, record_job, &probe)) {
        pbnfc_worker_pool_free(&pool);
        (void)pthread_mutex_destroy(&probe.mutex);
        return fail("first generation failed");
    }
    for (index = 0U; index < PBNFC_WORKER_POOL_SIZE; ++index) {
        if (probe.calls[index] != 1U) {
            pbnfc_worker_pool_free(&pool);
            (void)pthread_mutex_destroy(&probe.mutex);
            return fail("first generation did not invoke every worker once");
        }
    }
    probe.have_thread_ids = true;

    if (!pbnfc_worker_pool_run(&pool, record_job, &probe) ||
        !probe.have_thread_ids) {
        pbnfc_worker_pool_free(&pool);
        (void)pthread_mutex_destroy(&probe.mutex);
        return fail("workers were not reused for the second generation");
    }
    for (index = 0U; index < PBNFC_WORKER_POOL_SIZE; ++index) {
        if (probe.calls[index] != 2U) {
            pbnfc_worker_pool_free(&pool);
            (void)pthread_mutex_destroy(&probe.mutex);
            return fail("second generation did not invoke every worker once");
        }
    }

    probe.fail_worker = true;
    if (pbnfc_worker_pool_run(&pool, record_job, &probe)) {
        pbnfc_worker_pool_free(&pool);
        (void)pthread_mutex_destroy(&probe.mutex);
        return fail("worker failure was not propagated");
    }
    probe.fail_worker = false;
    pbnfc_worker_pool_shutdown(&pool);
    pbnfc_worker_pool_shutdown(&pool);
    if (pbnfc_worker_pool_worker_count(&pool) != 0U) {
        pbnfc_worker_pool_free(&pool);
        (void)pthread_mutex_destroy(&probe.mutex);
        return fail("shutdown did not clear the worker count");
    }
    pbnfc_worker_pool_free(&pool);
    (void)pthread_mutex_destroy(&probe.mutex);
    return 0;
}
